package com.jlas.learning.service.impl;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;

import java.io.IOException;
import java.io.InputStream;
import java.text.Normalizer;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * [JLAS-W0108] OD-D2-01 (owner 2026-10-23): grammar application questions the owner reviewed (DUYET) in the review
 * sheet. Learning's runtime copy {@code learning/grammar-application-reviewed.json} is generated by
 * {@code tools/learning-data-extract/grammar_question_review.mjs}; drafts never reach it. Keyed by the grammar pattern
 * as the DB grammar point carries it (Sekai {@code cong_thuc}), so every lesson that teaches the pattern can use it.
 */
final class ReviewedGrammarApplications {
    static final String RESOURCE = "learning/grammar-application-reviewed.json";

    record Item(String id, String level, String pattern, String contextVi, String promptJa, List<String> options,
            int correctIndex, String answerJa, String answerVi, String explanationVi) { }

    private static final ReviewedGrammarApplications SHARED = load();
    private final Map<String, List<Item>> byPattern;

    ReviewedGrammarApplications(List<Item> items) {
        Map<String, List<Item>> index = new HashMap<>();
        for (Item item : items) index.computeIfAbsent(key(item.pattern()), ignored -> new ArrayList<>()).add(item);
        index.replaceAll((pattern, list) -> List.copyOf(list));
        this.byPattern = Map.copyOf(index);
    }

    static ReviewedGrammarApplications shared() {
        return SHARED;
    }

    /** Reviewed items for a pattern; {@code level} narrows them when the point's level is known. */
    List<Item> forPattern(String pattern, String level) {
        List<Item> items = byPattern.getOrDefault(key(pattern), List.of());
        if (level == null) return items;
        return items.stream().filter(item -> item.level() == null || level.equals(item.level())).toList();
    }

    static String key(String pattern) {
        return pattern == null ? "" : Normalizer.normalize(pattern, Normalizer.Form.NFKC).replaceAll("[\\s〜～~]+", "");
    }

    private static ReviewedGrammarApplications load() {
        try (InputStream in = ReviewedGrammarApplications.class.getClassLoader().getResourceAsStream(RESOURCE)) {
            if (in == null) return new ReviewedGrammarApplications(List.of());
            List<Item> items = new ArrayList<>();
            for (JsonNode node : new ObjectMapper().readTree(in).path("items")) {
                List<String> options = new ArrayList<>();
                node.path("options").forEach(option -> options.add(option.asText()));
                items.add(new Item(node.path("id").asText(), node.path("level").asText(null), node.path("pattern").asText(),
                        node.path("context_vi").asText(""), node.path("prompt_ja").asText(""), List.copyOf(options),
                        node.path("correct_index").asInt(0), node.path("answer_ja").asText(""),
                        node.path("answer_vi").asText(""), node.path("explanation_vi").asText("")));
            }
            return new ReviewedGrammarApplications(items);
        } catch (IOException unreadable) {
            // A broken runtime copy must not stop the grammar check: it falls back to meaning questions only.
            return new ReviewedGrammarApplications(List.of());
        }
    }
}
